import { useEffect, useRef, useState, type KeyboardEvent } from "react";
import { noticeBlocks, type NoticeBlock } from "./notices";
import "./NoticesSheet.css";

/**
 * Help > Third-party Notices (⌘K, and the link at the shortcut sheet's
 * foot): THIRD_PARTY_NOTICES.md at the repo root, generated by
 * scripts/notices.mjs, read only when the sheet opens (its own chunk, about
 * 95 KB) and shown as headings, one row per package and the licence texts
 * in mono. Esc closes.
 */
export function NoticesSheet({ onClose }: { onClose: () => void }) {
  const [blocks, setBlocks] = useState<NoticeBlock[] | null>(null);
  const bodyRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    bodyRef.current?.focus();
    let live = true;
    void import("virtual:notices").then((m) => {
      if (live) setBlocks(noticeBlocks(m.default));
    });
    return () => {
      live = false;
    };
  }, []);

  const onKeyDown = (e: KeyboardEvent) => {
    if (e.key !== "Escape") return;
    e.preventDefault();
    e.stopPropagation();
    onClose();
  };

  return (
    <div
      className="tn-overlay"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="tn-sheet" role="dialog" aria-modal="true" aria-label="Third-party notices" data-notices onKeyDown={onKeyDown}>
        <div className="sheet-head">
          <h2 className="tn-title sheet-title">Third-party notices</h2>
          <button type="button" className="sheet-esc" title="Close  esc" onClick={onClose}>
            esc
          </button>
        </div>
        {/* Focused on open so Esc and the arrow / page keys work at once. */}
        <div ref={bodyRef} data-testid="tn-body" className="tn-body" tabIndex={0} data-loaded={blocks ? "" : undefined}>
          {blocks?.map((b, i) => {
            switch (b.kind) {
              case "h3":
                return <h3 key={i} className="tn-h3 sheet-label">{b.text}</h3>;
              case "h4":
                return <h4 key={i} className="tn-h4" data-licence={b.text}>{b.text}</h4>;
              case "p":
                return <p key={i} className="tn-p">{b.text}</p>;
              case "text":
                return <pre key={i} className="tn-text">{b.text}</pre>;
              case "list":
                return (
                  <ul key={i} className="tn-list">
                    {b.rows.map((r, j) => (
                      <li key={j} className="tn-row" data-package={r.name ?? undefined}>
                        {r.name && <span className="tn-name">{r.name}</span>}
                        <span>{r.rest}</span>
                        {r.who && <span className="tn-who">{r.who}</span>}
                      </li>
                    ))}
                  </ul>
                );
            }
          })}
        </div>
      </div>
    </div>
  );
}
